const charToInsert = inputChar || (seqIsPrintable ? seq : "");

if (charToInsert && !key.ctrl && !key.meta) {
  const result = insertText(input, cursorPosition, charToInsert);
  const { text: capped, position } = capToMaxLength(
    result.text,
    result.position,
    onTruncated
  );
  setInputState(capped);
  setCursorPositionState(position);
  setOriginalInput(capped);
}

update_md5_8caed4c63d419b1167fc466f32826.content_md5_8caed4c63d419b1167fc466f3282:
const charToInsert = inputChar || (seqIsPrintable ? seq : "");

// Note: some terminals mark regular typing as `meta` (e.g., AltGraph/IME quirks).
// We still want to accept printable text input; only block ctrl-modified chords.
if (charToInsert && !key.ctrl) {
  const result = insertText(input, cursorPosition, charToInsert);
  const { text: capped, position } = capToMaxLength(
    result.text,
    result.position,
    onTruncated
  );
  setInputState(capped);
  setCursorPositionState(position);
  setOriginalInput(capped);
}

