update_md5_e1f2d5296513482531e5641a323d9.content_md5_e1f2d5296513482531e5641a323d:
useInput((inputChar: string, key: Key) => {
  if (process.env.GROK_DEBUG_INPUT) {
    const seq = typeof key.sequence === "string" ? key.sequence : "";
    const safeSeq = seq.replaceAll("\n", "\\n").replaceAll("\r", "\\r").replaceAll("\t", "\\t");
    setLastKeyDebug(
      `char=${JSON.stringify(inputChar)} seq=${JSON.stringify(safeSeq)} name=${JSON.stringify(key.name)} ctrl=${!!key.ctrl} meta=${!!key.meta} shift=${!!key.shift}`
    );
  }
  handleInput(inputChar, key);
});

